const cases={"family":"<fieldset><legend>家庭成员</legend><label class=\"field\">姓名<input data-qa-key=\"guard.family.name\" type=\"text\" ></label><label class=\"field\">联系电话<input data-qa-key=\"guard.family.phone\" type=\"text\" ></label><label class=\"field\">与本人关系<input data-qa-key=\"guard.family.relationship\" type=\"text\" value=\"父亲\"></label></fieldset>","ambiguous":"<fieldset><legend>联系方式</legend><label class=\"field\">电子邮箱<input data-qa-key=\"guard.conflict\" type=\"text\" name=\"phone\"></label><label class=\"field\">联系资料<input data-qa-key=\"guard.unspecified\" type=\"text\" ></label><label class=\"field\">联系邮址<input data-qa-key=\"contact.email\" type=\"text\" ></label></fieldset>","changed":"<fieldset><legend>申请人资料</legend><label class=\"field\" id=\"mutable-label\">姓名<input data-qa-key=\"guard.changed\"></label><label class=\"field\">电子邮箱<input data-qa-key=\"contact.email\" type=\"text\" ></label></fieldset><button type=\"button\" id=\"mutate\">模拟网站改版</button>","occupied":"<label class=\"field\">姓名<input data-qa-key=\"guard.edited\" type=\"text\" ></label><label class=\"field\">电子邮箱<input data-qa-key=\"guard.occupied\" type=\"email\" value=\"existing@example.invalid\"></label><label class=\"field\">手机号码<input data-qa-key=\"guard.readonly\" type=\"tel\" readonly value=\"保留只读\"></label><label class=\"field\">作品集网址<input data-qa-key=\"guard.disabled\" type=\"url\" disabled value=\"https://example.invalid/existing\"></label><button type=\"button\" id=\"user-edit\">模拟用户修改姓名</button>","delay":"<div id=\"lazy-host\"></div><button type=\"button\" id=\"load-fields\">模拟延迟加载</button>","dynamic":"<div id=\"dynamic-rows\"><fieldset class=\"experience-row\"><legend>教育经历 1</legend><div class=\"grid\"><label class=\"field\">院校名称<input data-qa-key=\"education.0.school\" type=\"text\" ></label><label class=\"field\">专业<input data-qa-key=\"education.0.major\" type=\"text\" ></label><label class=\"field\">学历<select data-qa-key=\"education.0.degree\" ><option value=\"\">请选择</option><option value=\"bs\">本科</option><option value=\"ms\">硕士</option><option value=\"phd\">博士</option></select></label><label class=\"field\">入学时间<input data-qa-key=\"education.0.startDate\" type=\"month\" ></label><label class=\"field\">毕业时间<input data-qa-key=\"education.0.endDate\" type=\"month\" ></label></div></fieldset></div><button type=\"button\" id=\"add-delayed\">新增教育经历</button>","guarded":"<label class=\"field\">验证码<input data-qa-key=\"guard.captcha\" type=\"text\" ></label><label class=\"field\">密码<input data-qa-key=\"guard.password\" type=\"password\" ></label><label class=\"field\">身份证<input data-qa-key=\"guard.id\" type=\"text\" ></label><label><input data-qa-key=\"guard.consent\" type=\"checkbox\">我同意所有条款</label><fieldset><legend>紧急联系人</legend><label class=\"field\">姓名<input data-qa-key=\"guard.emergency.name\" type=\"text\" ></label><label class=\"field\">联系电话<input data-qa-key=\"guard.emergency.phone\" type=\"text\" ></label></fieldset><input type=\"hidden\" data-qa-key=\"guard.hidden\" value=\"untouched\"><label>简历上传<input type=\"file\" data-qa-key=\"guard.file\"></label>","precision":"<fieldset><legend>教育经历 2</legend><label class=\"field\">入学时间<input data-qa-key=\"guard.imprecise\" type=\"date\" ></label></fieldset><fieldset><legend>教育经历 1</legend><label class=\"field\">学历<select data-qa-key=\"guard.duplicate\" ><option value=\"\">请选择</option><option value=\"a\">本科</option><option value=\"b\">本科</option></select></label></fieldset><label class=\"field\">姓名<input data-qa-key=\"guard.tooshort\" type=\"text\" maxlength=\"2\"></label>","custom":"<label class=\"field\">居住城市<input role=\"combobox\" data-qa-key=\"guard.custom\" aria-label=\"居住城市\" readonly></label><div id=\"shadow\"></div><iframe title=\"内嵌申请表\" src=\"embedded.html\"></iframe>","network":"<label class=\"field\">姓名<input data-qa-key=\"contact.name\" type=\"text\" ></label><label class=\"field\">电子邮箱<input data-qa-key=\"contact.email\" type=\"text\" ></label><p>此模拟网站会在 input 时向本机接收器自动保存，用来验证「未提交」与「网站已读取」的区别。</p>"};const which=new URLSearchParams(location.search).get('case')||'family';document.querySelector('#case-form').innerHTML='<h2>场景：'+which+'</h2>'+cases[which]+'<button type="submit" class="danger">模拟提交（验收禁止点击）</button>';document.querySelector('#mutate')?.addEventListener('click',()=>{const l=document.querySelector('#mutable-label');l.firstChild.textContent='推荐人姓名';document.querySelector('[data-qa-key="guard.changed"]').setAttribute('name','referee')});document.querySelector('#user-edit')?.addEventListener('click',()=>{document.querySelector('[data-qa-key="guard.edited"]').value='人工刚刚修改，必须保留'});document.querySelector('#load-fields')?.addEventListener('click',()=>setTimeout(()=>{document.querySelector('#lazy-host').innerHTML="<label class=\"field\">姓名<input data-qa-key=\"contact.name\" type=\"text\" ></label><label class=\"field\">电子邮箱<input data-qa-key=\"contact.email\" type=\"text\" ></label>"},900));document.querySelector('#add-delayed')?.addEventListener('click',()=>{setTimeout(()=>document.querySelector('#dynamic-rows').insertAdjacentHTML('beforeend',"<fieldset class=\"experience-row\"><legend>教育经历 2</legend><div class=\"grid\"><label class=\"field\">院校名称<input data-qa-key=\"education.1.school\" type=\"text\" ></label><label class=\"field\">专业<input data-qa-key=\"education.1.major\" type=\"text\" ></label><label class=\"field\">学历<select data-qa-key=\"education.1.degree\" ><option value=\"\">请选择</option><option value=\"bs\">本科</option><option value=\"ms\">硕士</option><option value=\"phd\">博士</option></select></label><label class=\"field\">入学时间<input data-qa-key=\"education.1.startDate\" type=\"month\" ></label><label class=\"field\">毕业时间<input data-qa-key=\"education.1.endDate\" type=\"month\" ></label></div></fieldset>"),900)});if(which==='custom')document.querySelector('#shadow').attachShadow({mode:'open'}).innerHTML='<label>姓名<input aria-label="姓名"></label>';if(which==='network')document.querySelectorAll('input').forEach(e=>e.addEventListener('input',()=>fetch('http://127.0.0.1:47943/collect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:e.dataset.qaKey,value:e.value})})));